def longest_chain(pairs):
    # Create a dictionary to store the longest chain length for each number
    dp = {i: 1 for i in range(1, max(pairs) + 1)}

    # Iterate over each pair
    for i in range(1, max(pairs) + 1):
        for pair in pairs:
            if i == pair[0]:
                dp[i] = max(dp[i], dp[pair[1]] + 1)
            elif i > pair[0]:
                dp[i] = max(dp[i], dp[pair[1]] + 1)

    # Find the maximum value in the dictionary
    return max(dp.values())

