def find_median_sorted_arrays(arr1: list[int], arr2: list[int]) -> float:
    """Finds the median of two sorted arrays of the same size.

    Parameters:
    arr1 (list): First sorted list of integers.
    arr2 (list): Second sorted list of integers.

    Returns:
    float: The median of the combined sorted arrays.
    """
    n = len(arr1)

    # Base case for empty arrays (though specification assumes same size)
    if n == 0:
        raise ValueError("Arrays cannot be empty.")

    # Base case for arrays of size 1
    if n == 1:
        return (arr1[0] + arr2[0]) / 2.0

    # Base case for arrays of size 2
    if n == 2:
        return (max(arr1[0], arr2[0]) + min(arr1[1], arr2[1])) / 2.0

    # Helper function to find median of a single array
    def median(arr):
        mid = len(arr) // 2
        if len(arr) % 2 == 0:
            return (arr[mid - 1] + arr[mid]) / 2
        else:
            return arr[mid]

    m1 = median(arr1)
    m2 = median(arr2)

    # If medians are equal, m1 (or m2) is the median of the combined arrays
    if m1 == m2:
        return m1

    # If m1 < m2, then the median must lie in arr1[mid1:] and arr2[:mid2+1]
    mid = n // 2
    if m1 < m2:
        if n % 2 == 0:
            return find_median_sorted_arrays(arr1[mid - 1 :], arr2[: mid + 1])
        else:
            return find_median_sorted_arrays(arr1[mid:], arr2[: mid + 1])
    # If m1 > m2, then the median must lie in arr1[:mid1+1] and arr2[mid2:]
    else:
        if n % 2 == 0:
            return find_median_sorted_arrays(arr1[: mid + 1], arr2[mid - 1 :])
        else:
            return find_median_sorted_arrays(arr1[: mid + 1], arr2[mid:])


